import React from 'react';
import { CategoryLegendContainer, Dot, CategoryLegendContent } from './CategoryLegend.styles';
import { CategoryLegendProps } from './CategoryLegend.types';

const CategoryLegend = ({ caption, theme, orientation }: CategoryLegendProps): JSX.Element => (
  <CategoryLegendContainer orientation={orientation} key={caption}>
    <CategoryLegendContent theme={theme}>
      <Dot />
    </CategoryLegendContent>
    <span>{caption}</span>
  </CategoryLegendContainer>
);

export default CategoryLegend;
